import { Header } from './dist/esm/header.js'

export default function caseFn(input) {
  const buf = Buffer.alloc(512)
  buf.write('a', 0, 100)
  for (let i = 0; i < 12; i++) {
    buf[124 + i] = 0xFF
  }
  buf[156] = '0'.charCodeAt(0)
  buf.write('ustar\u000000', 257, 8)
  let sum = 0
  for (let i = 0; i < 512; i++) {
    if (i >= 148 && i < 160) {
      sum += 0x20
    } else {
      sum += buf[i]
    }
  }
  const cksumStr = Number(sum).toString(8).padStart(11, '0') + ' '
  buf.write(cksumStr, 148, 12, 'ascii')
  const h = new Header(buf)
  return { size: h.size }
}

