import { Header } from './dist/esm/header.js'

export default function caseFn(input) {
  if (input.type === 'ex-negative') {
    const h = new Header({ path: 'test', size: 100 })
    h.encode()
    // Create a new header with the block and a negative-size extended header
    const h2 = new Header(h.block, 0, { size: -50 }, undefined)
    return { size: h2.size }
  }
  if (input.type === 'gex-negative') {
    const h = new Header({ path: 'test', size: 100 })
    h.encode()
    // Create a new header with the block and a negative-size global extended header
    const h2 = new Header(h.block, 0, undefined, { size: -50 })
    return { size: h2.size }
  }
  if (input.type === 'gex-before-ex') {
    // Global extended header sets positive size, then local ex with negative should not override
    const h = new Header({ path: 'test', size: 100 })
    h.encode()
    const h2 = new Header(h.block, 0, { size: -50 }, { size: 200 })
    return { size: h2.size }
  }
  if (input.type === 'ex-first-then-gex') {
    // Global extended header sets negative size first, then local ex with positive should override it
    const h = new Header({ path: 'test', size: 100 })
    h.encode()
    const h2 = new Header(h.block, 0, { size: 300 }, { size: -50 })
    return { size: h2.size }
  }
}

